-- Lock the existing global rows before comparison/replacement.
SELECT e.id FROM "Exercise" e JOIN reviewed_exercise_muscles r ON r.id = e.id
WHERE e."ownerUserId" IS NULL ORDER BY e.id FOR UPDATE OF e;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM "Exercise" e JOIN reviewed_exercise_muscles r ON r.id=e.id
             WHERE e."ownerUserId" IS NULL AND e.name <> r.name) THEN
    RAISE EXCEPTION 'A reviewed exercise was renamed; revise the catalog before applying';
  END IF;
END $$;
CREATE TEMP TABLE changed_exercise_muscles ON COMMIT DROP AS
SELECT e.id, r.muscles FROM "Exercise" e JOIN reviewed_exercise_muscles r ON r.id=e.id AND r.name=e.name
WHERE e."ownerUserId" IS NULL AND r.muscles IS DISTINCT FROM
  (SELECT jsonb_agg(jsonb_build_object('muscleGroup', m."muscleGroup", 'role', m.role) ORDER BY m.role::text, m."muscleGroup"::text)
   FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id);
DELETE FROM "ExerciseMuscle" m USING changed_exercise_muscles c WHERE m."exerciseId"=c.id;
INSERT INTO "ExerciseMuscle" (id, "exerciseId", "muscleGroup", role, "createdAt")
SELECT gen_random_uuid()::text, c.id, (m->>'muscleGroup')::"MuscleGroup", (m->>'role')::"MuscleRole", CURRENT_TIMESTAMP
FROM changed_exercise_muscles c CROSS JOIN LATERAL jsonb_array_elements(c.muscles) m;
UPDATE "Exercise" e SET "updatedAt"=CURRENT_TIMESTAMP FROM changed_exercise_muscles c WHERE e.id=c.id;
COMMIT;
